    //   不放进 translateBare：那里是逐段跑，parts[2]、[4] 也是各自那一段的"开头"，
    //   可它们前面还跟着引号里的内容 —— 那不是行首。
    if (parts.length) parts[0] = dropLead(parts[0]);
