    //   是给老师看的字面量，一个字都不许动——它落在奇数段，本来就不进这个循环。
    // ★ 顺序有讲究：`修正方形`、`修正立体` 都必须跑在 translateBare **前面** ——
    //   它们认的是中文的「正方形」「正方体」，一旦 translateBare 先把名字换成
    //   `Polygon`／`Cube`，就再也认不出来了（补参／截参这一步会整个落空，
    //   而且落得没声音）。这两个之间谁先谁后无所谓，各认各的词。
    // ★ `修正立体` 得在**这一层**跑，不能塞进兜底：它要管的是
