    //   （备用写法）只认行首带 `名字=` 的，套在别人参数里的根本轮不到它。
    // ★ `修正正三角` 同一条规矩：它认的是「正三角形」这个中文词，也得赶在
    //   translateBare 前面；它吐出来的又是中文名（`多边形`／`正多边形`），
    //   正好交给同一趟 translateBare 翻。★ 它必须在这层、不进兜底，理由同 `修正立体`：
    //   模型写的 `正三角形` 可能嵌在别人参数里（`q=旋转(正三角形(A,B), 60°, A)`），
    //   兜底那些表只认行首 `名字=`，轮不到它。
